:where([data-moru-registry]) .ui-input-otp {
  font-family: var(--ui-font-family, inherit);
  color: var(--ui-text, #171717);
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.01em);
  box-sizing: border-box;
}
:where([data-moru-registry]) .ui-input-otp {
  --ui-size-height: var(--ui-control-height-md, var(--ui-control-height, 40px));
  --ui-size-padding-x: var(--ui-control-padding-x-md, 12px);
  --ui-size-icon: var(--ui-icon-size-md, 16px);
  --ui-resolved-control-height: max(
    var(--ui-size-height),
    calc(
      max(
          var(--ui-type-label-size, 14px) * var(--ui-type-label-line-height, 1.45),
          var(--ui-size-icon)
        ) +
        var(--ui-border-width, 1px) * 2 + var(--ui-space, 4px) * 2
    )
  );
}
:where([data-moru-registry]) .ui-input-otp[data-size='sm'] {
  --ui-size-height: var(--ui-control-height-sm, 32px);
  --ui-size-padding-x: var(--ui-control-padding-x-sm, 10px);
  --ui-size-icon: var(--ui-icon-size-sm, 14px);
}
:where([data-moru-registry]) .ui-input-otp[data-size='lg'] {
  --ui-size-height: var(--ui-control-height-lg, 48px);
  --ui-size-padding-x: var(--ui-control-padding-x-lg, 16px);
  --ui-size-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-input-otp:focus-within {
  outline: 2px solid var(--ui-focus-ring, var(--ui-ring, #181818));
  outline-offset: 3px;
}
:where([data-moru-registry]) .ui-input-otp[data-disabled] .ui-input-otp-slot {
  opacity: 1;
  color: var(--ui-disabled-text);
  background: var(--ui-disabled-bg);
  border-color: var(--ui-disabled-border);
  cursor: not-allowed;
  box-shadow: none;
}
:where([data-moru-registry]) .ui-input-otp {
  position: relative;
  max-width: 100%;
  width: max-content;
  border-radius: var(--ui-radius, 6px);
}
:where([data-moru-registry]) .ui-input-otp-control {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  min-width: 0;
  padding: 0;
  border: 0;
  outline: 0;
  opacity: 0.01;
  color: transparent;
  caret-color: transparent;
  background: transparent;
  font-size: 16px;
  cursor: text;
}
:where([data-moru-registry]) .ui-input-otp-control:is(:disabled, [aria-busy='true']) {
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-input-otp-slots {
  display: flex;
  align-items: stretch;
  gap: calc(var(--ui-control-gap, 8px) / 2);
  pointer-events: none;
}
:where([data-moru-registry]) .ui-input-otp-slot {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--ui-resolved-control-height);
  min-width: 0;
  min-height: var(--ui-resolved-control-height);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-input-bg, #f0f0ed);
  font-family: var(--ui-font-family-code, monospace);
  font-variant-numeric: tabular-nums;
  border-color: transparent;
}
:where([data-moru-registry]) .ui-input-otp-slot[data-active] {
  border-color: var(--ui-primary, #181818);
  box-shadow: inset 0 0 0 1px var(--ui-primary, #181818);
  background: var(--ui-surface, #fff);
}
:where([data-moru-registry]) .ui-input-otp[data-invalid]:not([data-disabled]) .ui-input-otp-slot {
  border-color: var(--ui-danger, #c14b45);
  background: var(--ui-danger-soft, #f9efef);
  box-shadow: 0 0 0 1px var(--ui-error-ring, var(--ui-danger, #c14b45));
}
:where([data-moru-registry]) .ui-input-otp[data-invalid]:not([data-disabled]):focus-within {
  outline-color: var(--ui-error-ring, var(--ui-danger, #c14b45));
}
:where([data-moru-registry]) .ui-input-otp-caret {
  display: block;
  width: 1px;
  height: 1.1em;
  background: currentColor;
  animation: moru-registry-ui-otp-blink 1s step-end infinite;
}
@keyframes moru-registry-ui-otp-blink {
  50% {
    opacity: 0;
  }
}
@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-input-otp {
    --ui-resolved-control-height: max(
      44px,
      var(--ui-size-height),
      calc(
        max(
            max(16px, var(--ui-type-label-size, 14px)) * var(--ui-type-label-line-height, 1.45),
            var(--ui-size-icon)
          ) +
          var(--ui-border-width, 1px) * 2 + var(--ui-space, 4px) * 2
      )
    );
  }
  :where([data-moru-registry]) .ui-input-otp-control {
    font-size: max(16px, var(--ui-type-label-size, 13px));
  }
}
@media (forced-colors: active) {
  :where([data-moru-registry]) .ui-input-otp-slot {
    border: 1px solid ButtonText;
  }
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-input-otp-caret {
    animation: none;
  }
}

:where([data-moru-registry]) .ui-input-otp[data-loading] {
  padding-inline-end: calc(var(--ui-size-icon, 16px) + var(--ui-control-gap, 8px) * 2);
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { forwardRef, useEffect, useRef, useState, type InputHTMLAttributes } from 'react'
import { Field as BaseField } from '@base-ui/react/field'
import { cn } from './_lib/cn'
import { mergeDescriptionIds, useFieldContext } from './field-context'
import {
  insertOTP,
  normalizeOTP,
  normalizeOTPLength,
  subscribeOTPFormReset,
} from './input-otp-utils'
import type { UIState } from './state'
import './controls-shared.css'
import './input-otp.css'

export type InputOTPProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'size' | 'value' | 'defaultValue' | 'onChange' | 'maxLength' | 'type' | 'inputMode' | 'pattern'
> & {
  length?: number
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  onComplete?: (value: string) => void
  size?: 'sm' | 'md' | 'lg'
  loading?: boolean
  previewState?: UIState
}

/** One real input preserves native selection, keyboard editing and one-time-code autofill. */
export const InputOTP = forwardRef<HTMLInputElement, InputOTPProps>(function InputOTP(
  {
    length = 6,
    value,
    defaultValue = '',
    onValueChange,
    onComplete,
    size = 'md',
    className,
    id,
    disabled,
    loading = false,
    previewState,
    readOnly,
    autoComplete = 'one-time-code',
    onSelect,
    onFocus,
    onBlur,
    onPaste,
    style,
    'aria-describedby': describedBy,
    'aria-invalid': invalid,
    ...props
  },
  forwardedRef,
) {
  const field = useFieldContext()
  const count = normalizeOTPLength(length)
  const busy = loading || previewState === 'loading'
  // Busy locks the code with readOnly, not disabled: the field keeps keyboard focus
  // (for example while a completed code is being verified) and still submits its value.
  const locked = disabled || previewState === 'disabled'
  const unavailable = locked || busy
  const resolvedInvalid =
    previewState === 'error' ? true : (invalid ?? (field?.invalid || undefined))
  const visuallyInvalid =
    resolvedInvalid !== undefined && resolvedInvalid !== false && resolvedInvalid !== 'false'
  const [internalValue, setInternalValue] = useState(() => normalizeOTP(defaultValue, count))
  const [focused, setFocused] = useState(false)
  const [caret, setCaret] = useState(0)
  const inputRef = useRef<HTMLInputElement | null>(null)
  const current = normalizeOTP(value ?? internalValue, count)
  const resetState = useRef({ value, defaultValue, count })
  resetState.current = { value, defaultValue, count }
  useEffect(() => {
    const form = inputRef.current?.form
    if (!form) return
    return subscribeOTPFormReset(
      form,
      () => {
        setInternalValue(normalizeOTP(resetState.current.defaultValue, resetState.current.count))
        setCaret(0)
      },
      () => resetState.current.value !== undefined,
    )
  }, [props.form])
  function change(next: string) {
    if (unavailable || readOnly || next === current) return
    if (value === undefined) setInternalValue(next)
    onValueChange?.(next)
    if (next.length === count) onComplete?.(next)
  }
  const input = (
    <input
      {...props}
      ref={(node) => {
        inputRef.current = node
        if (typeof forwardedRef === 'function') forwardedRef(node)
        else if (forwardedRef) forwardedRef.current = node
      }}
      {...(!field ? { id } : {})}
      className="ui-input-otp-control"
      value={current}
      type="text"
      inputMode="numeric"
      autoComplete={autoComplete}
      pattern={`[0-9]{${count}}`}
      maxLength={count}
      disabled={locked}
      readOnly={readOnly || busy}
      aria-describedby={mergeDescriptionIds(describedBy, field?.describedBy)}
      aria-invalid={resolvedInvalid}
      aria-busy={busy || undefined}
      onChange={(event) => {
        change(normalizeOTP(event.target.value, count))
        setCaret(event.target.selectionStart ?? count)
      }}
      onSelect={(event) => {
        setCaret(event.currentTarget.selectionStart ?? 0)
        onSelect?.(event)
      }}
      onFocus={(event) => {
        setFocused(true)
        setCaret(event.currentTarget.selectionStart ?? current.length)
        onFocus?.(event)
      }}
      onBlur={(event) => {
        setFocused(false)
        onBlur?.(event)
      }}
      onPaste={(event) => {
        onPaste?.(event)
        if (event.defaultPrevented || unavailable || readOnly) return
        event.preventDefault()
        const next = insertOTP(
          current,
          event.clipboardData.getData('text'),
          event.currentTarget.selectionStart ?? current.length,
          event.currentTarget.selectionEnd ?? current.length,
          count,
        )
        change(next.value)
        setCaret(next.caret)
        requestAnimationFrame(() => {
          inputRef.current?.setSelectionRange(next.caret, next.caret)
        })
      }}
    />
  )
  return (
    <div
      className={cn('ui-input-otp', className)}
      data-size={size}
      data-disabled={unavailable || undefined}
      data-invalid={visuallyInvalid || undefined}
      data-loading={busy || undefined}
      style={style}
    >
      {field ? (
        <BaseField.Control
          render={input}
          id={id ?? field.controlId}
          value={current}
          disabled={locked}
        />
      ) : (
        input
      )}
      {busy && (
        <span className="ui-control-loading-indicator ui-loading-indicator" aria-hidden="true" />
      )}
      <div className="ui-input-otp-slots" aria-hidden="true">
        {Array.from({ length: count }, (_, index) => (
          <span
            key={index}
            className="ui-input-otp-slot"
            data-active={(focused && Math.min(caret, count - 1) === index) || undefined}
          >
            {current[index] ??
              (focused && Math.min(caret, count - 1) === index ? (
                <span className="ui-input-otp-caret" />
              ) : null)}
          </span>
        ))}
      </div>
    </div>
  )
})
